CREATE TABLE IF NOT EXISTS accounts (id VARCHAR(32) PRIMARY KEY, tokens MEDIUMTEXT NOT NULL, expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (sku VARCHAR(80) PRIMARY KEY, supplier_sku VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, image VARCHAR(255), cost INT UNSIGNED NOT NULL, stock INT UNSIGNED NOT NULL, gtin VARCHAR(32)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS listings (external_id VARCHAR(32) PRIMARY KEY, sku VARCHAR(80) NOT NULL, price INT UNSIGNED NOT NULL, status VARCHAR(32) NOT NULL, FOREIGN KEY (sku) REFERENCES products(sku)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(80) PRIMARY KEY, account_id VARCHAR(32), status VARCHAR(40) NOT NULL, total INT UNSIGNED NOT NULL, payment_confirmed BOOLEAN NOT NULL DEFAULT 0, manual_approved BOOLEAN NOT NULL DEFAULT 0, logistics_validated BOOLEAN NOT NULL DEFAULT 0, fiscal_validated BOOLEAN NOT NULL DEFAULT 0, supplier_order_id VARCHAR(80) UNIQUE, supplier_paid BOOLEAN NOT NULL DEFAULT 0, label_prepared BOOLEAN NOT NULL DEFAULT 0, shipment_id VARCHAR(32), simulated BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_lines (order_id VARCHAR(80) NOT NULL, sku VARCHAR(80) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_cost INT UNSIGNED NOT NULL, PRIMARY KEY(order_id,sku), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(sku) REFERENCES products(sku)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(80) NOT NULL, event VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS webhook_events (id CHAR(64) PRIMARY KEY, topic VARCHAR(32) NOT NULL, resource VARCHAR(255) NOT NULL, account_id VARCHAR(32) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, next_run BIGINT NOT NULL DEFAULT 0, last_error VARCHAR(40), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX queue_idx(status,next_run)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(40) NOT NULL, action VARCHAR(80) NOT NULL, entity_id VARCHAR(80), outcome VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 1, expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, value MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS drafts (id CHAR(32) PRIMARY KEY, sku VARCHAR(80) NOT NULL, title VARCHAR(255) NOT NULL, price INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(sku) REFERENCES products(sku)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
